INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — QTIP trust election and marital deduction
(3, 'Estate and Gift Tax', 'Palmer dies in 2026, leaving a $6,000,000 trust for his wife, Caldwell. The trust pays all income to Caldwell annually for life, with the remainder passing to Palmer''s children. The executor files Form 706 and makes a QTIP election under IRC Section 2056(b)(7). What is the estate tax marital deduction for this trust?', '["$0, because the trust is a terminable interest", "$3,000,000, limited to one-half of the trust value", "$6,000,000, the full value of the qualified trust", "$6,000,000 minus the present value of the remainder interest"]'::jsonb, 2, 'Under IRC Section 2056(b)(7), a QTIP election allows the full value of a qualified terminable interest trust to qualify for the marital deduction, provided the surviving spouse receives all income for life and the executor makes a timely election on Form 706. The $6,000,000 trust qualifies in full because the income requirement is met. Choice A is incorrect because the QTIP election is an explicit exception to the terminable interest rule, overriding the general disqualification.', 'medium', 2),

-- Q2: easy / L1 — Taxable termination definition under GST
(3, 'Estate and Gift Tax', 'Under IRC Chapter 13, what is a taxable termination for generation-skipping transfer tax purposes?', '["A direct transfer of property to a skip person", "A termination of an interest in a trust where only skip persons remain as beneficiaries", "A lapse of a power of appointment held by a non-skip person", "A distribution from a trust to a non-skip person"]'::jsonb, 1, 'Under IRC Section 2612(a), a taxable termination occurs when an interest in a trust terminates and only skip persons hold interests in the trust afterward. This triggers GST tax because the property effectively passes down a generation. Choice A is incorrect because a direct transfer to a skip person is classified as a direct skip under Section 2612(c), not a taxable termination.', 'easy', 1),

-- Q3: hard / L4 — Evaluate GRAT vs outright gift for estate reduction
(3, 'Estate and Gift Tax', 'Mercer, age 65, holds $4,000,000 in appreciated stock. Her estate planner presents two options: an outright gift using the lifetime exemption, or a two-year zeroed-out grantor retained annuity trust (GRAT) funded with the same stock. The stock is expected to appreciate 12% annually, well above the Section 7520 rate. Evaluate which strategy is more tax-efficient for Mercer.', '["The GRAT is more tax-efficient because excess appreciation passes to the children transfer-tax-free", "The outright gift is more tax-efficient because it freezes the value at today''s FMV", "Both strategies produce identical transfer tax results", "The GRAT is less efficient because the entire trust value remains in the gross estate"]'::jsonb, 0, 'Under IRC Section 2702, a GRAT allows the grantor to retain annuity payments while transferring the remainder to beneficiaries. When trust assets appreciate above the Section 7520 hurdle rate, the excess growth passes to the children free of gift and estate tax. A zeroed-out GRAT achieves this with near-zero taxable gift, preserving the lifetime exemption. Choice B is incorrect because while an outright gift freezes value, it consumes $4,000,000 of exemption, whereas the GRAT achieves the same freeze with minimal exemption usage.', 'hard', 4),

-- Q4: easy / L1 — Gift tax return filing deadline
(3, 'Estate and Gift Tax', 'Under IRC Section 6075(b), when is the federal gift tax return (Form 709) generally due?', '["December 31 of the year the gift was made", "90 days after the date of the gift", "The last day of the month following the gift", "April 15 of the year following the gift"]'::jsonb, 3, 'Under IRC Section 6075(b), the gift tax return (Form 709) must be filed by April 15 of the calendar year following the year in which the taxable gift was made. This deadline aligns with the income tax return due date. Choice A is incorrect because the return is not due in the same calendar year as the gift but rather by the following year''s income tax deadline.', 'easy', 1),

-- Q5: easy / L1 — General power of appointment definition
(3, 'Estate and Gift Tax', 'Under IRC Section 2041, what is a general power of appointment?', '["A power exercisable in favor of the holder, the holder''s estate, the holder''s creditors, or creditors of the holder''s estate", "A power limited to an ascertainable standard relating to health, education, maintenance, or support", "A power that can only be exercised with the consent of all trust beneficiaries", "A power held by a trustee to distribute income among a class of beneficiaries"]'::jsonb, 0, 'Under IRC Section 2041(b)(1), a general power of appointment is one exercisable in favor of the holder, the holder''s estate, the holder''s creditors, or creditors of the holder''s estate. Property subject to such a power is included in the holder''s gross estate. Choice B is incorrect because a power limited to an ascertainable standard (HEMS) is specifically excluded from the definition of a general power under Section 2041(b)(1)(A).', 'easy', 1),

-- Q6: medium / L3 — Effect of three-year rule on life insurance transfer
(3, 'Estate and Gift Tax', 'Franklin transferred ownership of a $2,000,000 life insurance policy to an irrevocable life insurance trust on March 1, 2024. Franklin retained no incidents of ownership after the transfer. Franklin dies unexpectedly on January 15, 2026. How does the three-year rule affect the estate tax treatment of this policy?', '["The policy is excluded from the gross estate because Franklin held no incidents of ownership at death", "The death benefit is excluded because the transfer was to an irrevocable trust", "The $2,000,000 death benefit is included in Franklin''s gross estate because the transfer occurred within three years of death", "Only the cash surrender value at the date of transfer is included in the gross estate"]'::jsonb, 2, 'Under IRC Section 2035(a), if a decedent transfers a life insurance policy within three years of death, the full death benefit is included in the gross estate. Franklin transferred the policy in March 2024 and died in January 2026, less than three years later, so the entire $2,000,000 is includable. Choice A is incorrect because even though Franklin relinquished all incidents of ownership, Section 2035 overrides this exclusion for transfers made within the three-year window.', 'medium', 3),

-- Q7: easy / L1 — Special use valuation purpose
(3, 'Estate and Gift Tax', 'Under IRC Section 2032A, what does the special use valuation election permit?', '["Valuing all estate assets at their cost basis rather than fair market value", "Valuing qualified real property used in farming or a closely held business at its current use value rather than highest-and-best-use value", "Deferring estate tax payments for up to 15 years on any real property", "Reducing the gross estate by the amount of appreciation occurring after the decedent''s death"]'::jsonb, 1, 'Under IRC Section 2032A, the special use valuation election allows qualified real property used in farming or a closely held business to be valued at its current use value instead of its fair market value based on highest-and-best-use. This can significantly reduce the gross estate for qualifying farms and businesses. Choice A is incorrect because Section 2032A applies only to qualified real property, not all estate assets, and uses current use value rather than cost basis.', 'easy', 1),

-- Q8: hard / L4 — Evaluate net gift arrangement vs standard gift
(3, 'Estate and Gift Tax', 'Winters, age 72, has a $25,000,000 estate and no remaining lifetime exemption. She plans to gift $5,000,000 in marketable securities to her son, Reeves. Her estate planner suggests a net gift arrangement where Reeves agrees to pay any resulting gift tax. The gift tax rate is 40%. Evaluate the primary advantage of the net gift arrangement for Winters.', '["The net gift eliminates all gift tax on the transfer", "The net gift defers gift tax until Reeves sells the securities", "The net gift increases Reeves''s basis in the securities", "The net gift reduces Winters''s taxable gift because the gift tax paid by Reeves reduces the value transferred"]'::jsonb, 3, 'Under IRC Section 2512 and Rev. Rul. 75-72, in a net gift arrangement the donee''s obligation to pay gift tax is treated as consideration, reducing the value of the taxable gift. The taxable gift equals the FMV minus the gift tax paid by the donee, creating a circular calculation that lowers the total transfer tax cost. Choice A is incorrect because a net gift does not eliminate gift tax; it shifts the payment obligation to the donee while reducing the taxable amount.', 'hard', 4),

-- Q9: medium / L2 — Gift of encumbered property calculation
(3, 'Estate and Gift Tax', 'On June 10, 2026, Dawson gifts a rental property with a fair market value of $500,000 and an outstanding mortgage of $180,000 to his daughter, Vega. Vega assumes the mortgage. Dawson''s adjusted basis in the property is $220,000. Under IRC Section 2512, what is the amount of Dawson''s taxable gift before the annual exclusion?', '["$500,000", "$320,000", "$280,000", "$220,000"]'::jsonb, 1, 'Under IRC Section 2512, when a donor gifts encumbered property and the donee assumes the liability, the taxable gift equals the fair market value minus the assumed debt. Dawson''s gift is $500,000 FMV minus the $180,000 mortgage assumed by Vega, resulting in a $320,000 taxable gift before the annual exclusion. Choice A is incorrect because it fails to subtract the mortgage liability that Vega assumed, which reduces the net value of the transfer.', 'medium', 2),

-- Q10: hard / L4 — Evaluate Section 6166 installment election for closely-held business
(3, 'Estate and Gift Tax', 'Ortega dies in 2026 with a gross estate of $22,000,000, including a 60% interest in a closely held manufacturing business valued at $14,000,000. The estate owes approximately $3,000,000 in federal estate tax and holds $1,500,000 in liquid assets. Evaluate whether the IRC Section 6166 installment election is appropriate for Ortega''s estate.', '["The election is appropriate because it allows the estate to defer payment of estate tax attributable to the business interest for up to 14 years with a favorable interest rate", "The election is inappropriate because the business interest does not exceed 50% of the adjusted gross estate", "The election allows indefinite deferral of all estate taxes regardless of asset composition", "The election only applies to farming operations and does not cover manufacturing businesses"]'::jsonb, 0, 'Under IRC Section 6166, an estate may elect to pay estate tax attributable to a closely held business interest in installments over up to 14 years (4-year deferral plus 10 annual payments) if the business exceeds 35% of the adjusted gross estate. Ortega''s $14,000,000 business interest is approximately 64% of the gross estate, easily meeting the threshold. Choice B is incorrect because the threshold is 35%, not 50%, of the adjusted gross estate.', 'hard', 4),

-- Q11: medium / L2 — Below-market demand loan gift treatment
(3, 'Estate and Gift Tax', 'On January 1, 2026, Lancaster makes an interest-free demand loan of $800,000 to her adult son, Pryor. The applicable federal rate is 5%. Under IRC Section 7872, what is the annual deemed gift amount from Lancaster to Pryor?', '["$0, because loans between family members are not subject to gift tax", "$800,000, the full principal amount", "$40,000, the forgone interest at the applicable federal rate", "$19,000, limited to the annual exclusion amount"]'::jsonb, 2, 'Under IRC Section 7872, a below-market demand loan between family members creates a deemed gift equal to the forgone interest. The annual deemed gift is calculated as the difference between the interest at the applicable federal rate and the actual interest paid. On $800,000 at 5% AFR with 0% charged, the deemed gift is $40,000 ($800,000 times 5%). Choice B is incorrect because the gift is measured by the forgone interest, not the principal amount, which remains a loan obligation.', 'medium', 2),

-- Q12: easy / L1 — Estate tax return due date
(3, 'Estate and Gift Tax', 'Under IRC Section 6075(a), when must a federal estate tax return (Form 706) be filed?', '["Within 60 days of the decedent''s death", "Within 6 months of the decedent''s death", "Within 9 months of the decedent''s death", "By April 15 of the year following the decedent''s death"]'::jsonb, 2, 'Under IRC Section 6075(a), the federal estate tax return (Form 706) must be filed within nine months after the date of the decedent''s death. An automatic six-month extension may be obtained by filing Form 4768. Choice D is incorrect because the April 15 deadline applies to income tax and gift tax returns, not estate tax returns, which follow the nine-month rule from the date of death.', 'easy', 1),

-- Q13: medium / L2 — Adjusted taxable gifts in estate tax computation
(3, 'Estate and Gift Tax', 'Rivera dies in 2026 with a gross estate of $16,000,000 and allowable deductions of $2,000,000. During her lifetime, Rivera made $3,000,000 in adjusted taxable gifts on which no gift tax was paid due to the unified credit. Under IRC Section 2001, what is the estate tax base used to compute the tentative estate tax?', '["$17,000,000, the taxable estate plus adjusted taxable gifts", "$16,000,000, the gross estate before deductions", "$14,000,000, the taxable estate only", "$19,000,000, the gross estate plus adjusted taxable gifts"]'::jsonb, 0, 'Under IRC Section 2001(b), the tentative estate tax is computed on the sum of the taxable estate ($16,000,000 minus $2,000,000 equals $14,000,000) plus adjusted taxable gifts ($3,000,000), yielding an estate tax base of $17,000,000. This unified approach ensures lifetime gifts are accounted for in the progressive rate schedule. Choice C is incorrect because it omits the $3,000,000 in adjusted taxable gifts, which must be added back to prevent circumvention of the progressive rates.', 'medium', 2),

-- Q14: medium / L2 — Community property estate inclusion
(3, 'Estate and Gift Tax', 'Grant and Hale are married and reside in a community property state. Grant dies in 2026 owning community property with a total fair market value of $4,000,000. Grant also owns $1,200,000 in separate property. Under IRC Section 2033, what amount is included in Grant''s gross estate?', '["$4,000,000, the entire community property", "$3,200,000, one-half of community property plus separate property", "$5,200,000, all community and separate property", "$1,200,000, only the separate property"]'::jsonb, 1, 'Under IRC Section 2033, only the decedent''s interest in property is included in the gross estate. In a community property state, each spouse owns one-half of community property. Grant''s gross estate includes $2,000,000 (half of the $4,000,000 community property) plus $1,200,000 in separate property, totaling $3,200,000. Choice A is incorrect because only Grant''s one-half interest in community property is includable; the other half belongs to Hale outright.', 'medium', 2),

-- Q15: medium / L2 — Gift of future interest (no annual exclusion)
(3, 'Estate and Gift Tax', 'On August 5, 2026, Brennan transfers $200,000 to an irrevocable trust for his nephew, Cortez. The trust provides that Cortez will receive all income and principal when Cortez turns 30 in 2034. The trust contains no Crummey withdrawal provision. What portion of Brennan''s transfer qualifies for the annual gift tax exclusion?', '["$19,000, the full annual exclusion", "$200,000, the entire transfer", "$0, because the gift is a future interest", "$181,000, the transfer minus one annual exclusion"]'::jsonb, 2, 'Under IRC Section 2503(b), the annual gift tax exclusion applies only to gifts of present interests, meaning the donee must have an immediate, unrestricted right to use or enjoy the property. Because Cortez cannot access the trust until 2034 and no Crummey withdrawal power exists, the entire $200,000 is a future interest that does not qualify. Choice A is incorrect because the annual exclusion requires a present interest, which this trust structure fails to provide.', 'medium', 2),

-- Q16: easy / L1 — Charitable deduction for gift tax purposes
(3, 'Estate and Gift Tax', 'Under IRC Section 2522, what is the gift tax charitable deduction?', '["An unlimited deduction for qualifying gifts made to eligible charitable organizations", "A deduction limited to 60% of the donor''s adjusted gross income", "A deduction capped at $1,000,000 per calendar year for charitable transfers", "A deduction available only for gifts made at death through a will"]'::jsonb, 0, 'Under IRC Section 2522, donors may claim an unlimited gift tax charitable deduction for qualifying transfers to eligible charitable organizations. Unlike the income tax charitable deduction, which has AGI-based limitations, the gift tax charitable deduction has no percentage or dollar cap. Choice B is incorrect because the 60% AGI limitation applies to income tax charitable deductions under Section 170, not to gift tax charitable deductions under Section 2522.', 'easy', 1),

-- Q17: medium / L3 — Effect of valuation discount on taxable gift of FLP interest
(3, 'Estate and Gift Tax', 'Thornton, age 70, transfers a 25% limited partnership interest in Thornton Family Partners LP to her daughter, Keane, on September 12, 2026. The partnership holds marketable securities worth $8,000,000 total. A qualified appraiser applies a 30% combined discount for lack of marketability and minority interest. How does the valuation discount affect the taxable gift?', '["The discount has no effect because partnership interests must be valued at the proportionate share of underlying assets", "The discount increases the taxable gift by adding a control premium", "The discount is disallowed under IRC Section 2704 for family-controlled entities", "The discount reduces the taxable gift from $2,000,000 to $1,400,000 because the transferred interest lacks control and marketability"]'::jsonb, 3, 'Under IRC Section 2512 and Treasury Regulation 25.2512-1, gifts are valued at fair market value, which for minority interests in family partnerships reflects discounts for lack of marketability and lack of control. Thornton''s proportionate share is $2,000,000 (25% of $8,000,000), but the 30% combined discount reduces the taxable gift to $1,400,000. Choice A is incorrect because the IRS and courts recognize that a minority limited partnership interest is worth less than its proportionate share of underlying assets due to transfer and control restrictions.', 'medium', 3),

-- Q18: medium / L3 — Effect of retained income interest on gross estate inclusion
(3, 'Estate and Gift Tax', 'Nakamura transfers $3,500,000 in investment assets to an irrevocable trust on February 1, 2024, naming her children as beneficiaries. The trust instrument grants Nakamura the right to receive all trust income for ten years. Nakamura dies on November 20, 2026. Analyze the estate tax consequence of Nakamura''s retained income interest.', '["Only the value of the income interest at the date of death is included in the gross estate", "The full fair market value of the trust assets at Nakamura''s death is included in the gross estate under IRC Section 2036", "The trust assets are excluded because the transfer was completed more than one year before death", "Only the original $3,500,000 transfer value is included, with no adjustment for appreciation"]'::jsonb, 1, 'Under IRC Section 2036(a)(1), if a decedent transfers property but retains the right to income for life or any period not determinable without reference to death, the full date-of-death value of the transferred property is included in the gross estate. Nakamura retained the right to all trust income, triggering full inclusion at current fair market value. Choice A is incorrect because Section 2036 includes the entire trust corpus, not merely the value of the retained income interest.', 'medium', 3),

-- Q19: easy / L2 — Revocable trust gross estate inclusion
(3, 'Estate and Gift Tax', 'Harris creates a revocable living trust in 2020 and transfers $750,000 in assets to the trust. At Harris''s death in 2026, the trust assets have grown to $1,100,000. What amount is included in Harris''s gross estate?', '["$0, because the assets are held in a trust", "$750,000, the original transfer amount", "$1,100,000, the date-of-death value of the trust assets", "$350,000, only the appreciation since the transfer"]'::jsonb, 2, 'Under IRC Section 2038, property transferred to a revocable trust is included in the decedent''s gross estate at its date-of-death fair market value because the decedent retained the power to alter, amend, or revoke the trust. Harris''s trust is valued at $1,100,000 for estate tax purposes. Choice B is incorrect because the inclusion amount is the current fair market value at death, not the original transfer amount, as Section 2038 looks to the date-of-death value.', 'easy', 2),

-- Q20: hard / L3 — Analyzing interplay of Section 2035 and incidents of ownership
(3, 'Estate and Gift Tax', 'Pearson transferred all incidents of ownership in a $3,000,000 life insurance policy to an ILIT on April 10, 2022. On June 1, 2025, Pearson exercised a policy dividend option by directing dividends to purchase paid-up additions. Pearson dies on March 5, 2026, with a total death benefit of $3,200,000. Analyze whether the policy proceeds are included in Pearson''s gross estate.', '["Only the $200,000 in paid-up additions is included because Pearson exercised incidents of ownership over the additions only", "The full $3,200,000 is excluded because the original transfer occurred more than three years before death", "Only the cash surrender value of the policy is included in the gross estate", "The full $3,200,000 is included because Pearson''s exercise of the dividend option constituted an incident of ownership under IRC Section 2042"]'::jsonb, 3, 'Under IRC Section 2042, life insurance proceeds are included in the gross estate if the decedent possessed any incidents of ownership at death. By exercising the dividend option and directing the purchase of paid-up additions, Pearson retained an incident of ownership over the policy. Because Pearson held this incident within three years of death, Section 2035 also applies. The full $3,200,000 is includable. Choice B is incorrect because Pearson''s subsequent exercise of incidents of ownership restarted the three-year analysis.', 'hard', 3),

-- Q21: easy / L1 — Unified transfer tax system definition
(3, 'Estate and Gift Tax', 'What is the unified transfer tax system under the Internal Revenue Code?', '["A system that taxes only transfers at death, not lifetime gifts", "A system that combines the estate tax and gift tax under a single cumulative rate schedule and shared exemption", "A system that exempts all transfers between related parties from taxation", "A system that applies different rate schedules to gift and estate transfers"]'::jsonb, 1, 'The unified transfer tax system under IRC Sections 2001 and 2502 combines the estate tax and gift tax into a single framework using one cumulative rate schedule and a shared applicable exclusion amount. Lifetime gifts and transfers at death are taxed together to prevent avoidance through lifetime gifting. Choice D is incorrect because the hallmark of the unified system is that the same rate schedule applies to both gift and estate transfers, not separate schedules.', 'easy', 1),

-- Q22: medium / L2 — Charitable remainder trust gift tax deduction
(3, 'Estate and Gift Tax', 'On October 1, 2026, Montgomery transfers $2,000,000 to a charitable remainder annuity trust that pays Montgomery $120,000 annually for 15 years, after which the remainder passes to a qualified charity. The present value of the charitable remainder interest is $820,000 under the Section 7520 tables. What is Montgomery''s gift tax charitable deduction?', '["$820,000, the present value of the charitable remainder interest", "$2,000,000, the full value of the property transferred", "$1,180,000, the present value of the annuity interest", "$0, because Montgomery retained an income interest"]'::jsonb, 0, 'Under IRC Section 2522(c)(2), a gift tax charitable deduction is allowed for the present value of the remainder interest passing to a qualifying charity from a charitable remainder annuity trust. The deduction equals $820,000, the actuarially determined value of the charity''s remainder interest. Choice D is incorrect because retaining an income interest does not disqualify the charitable deduction; the Code specifically provides for split-interest trust deductions when the trust meets CRAT requirements.', 'medium', 2),

-- Q23: medium / L3 — Effect of gift splitting on GST exemption allocation
(3, 'Estate and Gift Tax', 'Bennett and Foster, a married couple, give $500,000 to a trust for the sole benefit of their grandchild, Dawkins, in 2026. They elect gift splitting on Form 709. Each spouse has $6,000,000 remaining in GST exemption. Analyze how the gift-splitting election affects the allocation of GST exemption.', '["Gift splitting has no effect on GST exemption because GST is calculated on the total transfer", "Only the donor spouse may allocate GST exemption to the transfer", "Gift splitting doubles the GST exemption available, eliminating the need for allocation", "Each spouse is treated as the transferor of $250,000 and may independently allocate GST exemption to their respective share"]'::jsonb, 3, 'Under IRC Section 2652(a)(2), when spouses elect gift splitting, each spouse is treated as the transferor of one-half of the gift for GST purposes. Bennett and Foster are each treated as transferring $250,000 and may independently allocate their own GST exemption to cover their share, allowing both exemptions to shelter the transfer. Choice A is incorrect because gift splitting directly affects GST treatment by creating two deemed transferors, each with separate exemption allocation rights.', 'medium', 3),

-- Q24: medium / L2 — Basis of inherited community property (double step-up)
(3, 'Estate and Gift Tax', 'Elliott and Warren are married in a community property state. They purchased stock as community property for $200,000. When Elliott dies in 2026, the stock is worth $900,000. Warren inherits Elliott''s half under the will. Under IRC Section 1014(b)(6), what is Warren''s total basis in the entire stock?', '["$200,000, the original cost basis", "$550,000, a step-up on only the decedent''s half", "$900,000, because both halves receive a step-up to fair market value", "$450,000, only the decedent''s half at fair market value"]'::jsonb, 2, 'Under IRC Section 1014(b)(6), when community property is included in a decedent''s gross estate, both the decedent''s half and the surviving spouse''s half receive a stepped-up basis to fair market value at death. Warren''s total basis becomes $900,000 ($450,000 for each half). Choice B is incorrect because Section 1014(b)(6) provides a unique double step-up for community property, unlike separate property where only the decedent''s share receives a basis adjustment.', 'medium', 2),

-- Q25: hard / L4 — Evaluate qualified disclaimer strategy to reduce combined estate tax
(3, 'Estate and Gift Tax', 'Hutchins dies in 2026 leaving $20,000,000 to his wife, Simmons, via the marital deduction. Simmons has $10,000,000 in her own name and no remaining lifetime exemption. Their estate planner advises Simmons to disclaim $6,000,000 under IRC Section 2518, directing it to a bypass trust for the children. Evaluate the estate planning benefit of this disclaimer strategy.', '["The disclaimer has no tax benefit because the marital deduction already eliminates estate tax on Hutchins''s estate", "The disclaimer reduces the combined estate tax on both estates by sheltering $6,000,000 from tax in Simmons''s estate using Hutchins''s exemption", "The disclaimer triggers immediate gift tax because Simmons is directing property to the children", "The disclaimer is invalid because a surviving spouse cannot disclaim property passing under a will"]'::jsonb, 1, 'Under IRC Section 2518, a qualified disclaimer allows Simmons to redirect $6,000,000 to a bypass trust utilizing Hutchins''s applicable exclusion amount. Without the disclaimer, the entire $20,000,000 would be in Simmons''s estate (totaling $30,000,000), exposing significantly more to estate tax at her death. The disclaimer shelters $6,000,000 from both estates. Choice C is incorrect because a qualified disclaimer is not treated as a gift; the property passes as though the disclaimant predeceased the decedent.', 'hard', 4),

-- Q26: medium / L3 — Effect of survivorship clause on marital deduction
(3, 'Estate and Gift Tax', 'Chambers dies on May 1, 2026. Her will leaves the entire estate to her husband, Adler, subject to a six-month survivorship clause requiring Adler to survive until November 1, 2026. Adler is alive and healthy. Analyze the effect of the survivorship clause on the marital deduction.', '["The marital deduction is available because the survivorship period does not exceed six months under IRC Section 2056(b)(3)", "The marital deduction is denied because any survivorship clause creates a terminable interest", "The marital deduction is reduced by 50% when a survivorship clause is used", "The marital deduction is deferred until the survivorship period expires"]'::jsonb, 0, 'Under IRC Section 2056(b)(3), a survivorship condition does not disqualify a bequest from the marital deduction if the condition requires survival for no more than six months and the surviving spouse in fact survives. Chambers''s six-month clause meets both requirements since Adler survived. Choice B is incorrect because Section 2056(b)(3) provides a specific exception to the terminable interest rule for survivorship clauses of six months or less.', 'medium', 3),

-- Q27: hard / L4 — Evaluate IRS challenge to family limited partnership
(3, 'Estate and Gift Tax', 'Vasquez, age 80, creates a family limited partnership, contributes $10,000,000 in marketable securities, and immediately gifts 90% limited partnership interests to her three children with a 35% valuation discount. Vasquez retains the 10% general partner interest and has no business purpose for the FLP beyond tax savings. Evaluate the most likely IRS challenge to this transaction.', '["The IRS will argue that the gifts are incomplete because Vasquez retained a general partner interest", "The IRS will challenge the discount percentage only, accepting the FLP structure as valid", "The IRS will likely invoke IRC Section 2036(a) to include the transferred assets in Vasquez''s gross estate because the FLP lacked a legitimate business purpose and Vasquez retained control", "The IRS will reclassify the limited partnership interests as general partnership interests"]'::jsonb, 2, 'Under IRC Section 2036(a), the IRS has successfully challenged FLPs formed primarily for tax avoidance, arguing that the decedent retained enjoyment or control over contributed assets. Courts in cases like Estate of Bongard apply Section 2036 when the FLP lacks a legitimate nontax business purpose and the decedent retained control as general partner. Choice B is incorrect because the IRS typically challenges the entire structure under Section 2036, not just the discount, when no bona fide business purpose exists.', 'hard', 4),

-- Q28: medium / L3 — Effect of state death tax deduction on federal taxable estate
(3, 'Estate and Gift Tax', 'Patterson dies in 2026 with a taxable estate of $18,000,000 before considering state death taxes. The estate owes $1,200,000 in state estate tax. Analyze how the state estate tax payment affects Patterson''s federal estate tax computation.', '["The state estate tax has no effect on the federal estate tax computation", "The $1,200,000 state estate tax is deductible under IRC Section 2058, reducing the federal taxable estate to $16,800,000", "The state estate tax generates a dollar-for-dollar credit against the federal estate tax", "The state estate tax reduces the gross estate rather than the taxable estate"]'::jsonb, 1, 'Under IRC Section 2058, estates may deduct state death taxes paid from the federal taxable estate. The $1,200,000 state estate tax reduces Patterson''s federal taxable estate from $18,000,000 to $16,800,000. This provision replaced the former state death tax credit, which was phased out. Choice C is incorrect because the state death tax credit was repealed for decedents dying after 2004; current law provides only a deduction under Section 2058, not a credit.', 'medium', 3),

-- Q29: easy / L1 — Incidents of ownership definition for life insurance
(3, 'Estate and Gift Tax', 'Under IRC Section 2042, what are incidents of ownership in a life insurance policy?', '["The cash surrender value of the policy at the date of death", "The total premiums paid by the insured over the policy''s life", "The amount of the death benefit payable to named beneficiaries", "Rights such as the power to change beneficiaries, borrow against the policy, or cancel the policy"]'::jsonb, 3, 'Under IRC Section 2042(2), incidents of ownership include any economic rights in a life insurance policy, such as the power to change beneficiaries, surrender or cancel the policy, borrow against the cash value, or assign the policy. If the decedent held any incidents at death, the full death benefit is included in the gross estate. Choice A is incorrect because incidents of ownership refer to rights of control over the policy, not the cash surrender value.', 'easy', 1),

-- Q30: medium / L3 — Effect of incomplete gift on gift tax liability
(3, 'Estate and Gift Tax', 'Donovan transfers $1,500,000 to a trust on March 15, 2026, but reserves the right to revoke the trust and reclaim the assets at any time. Donovan''s accountant asks whether a gift tax return is required. Analyze whether this transfer constitutes a completed gift for gift tax purposes.', '["The transfer is not a completed gift because Donovan''s retained revocation power means dominion and control have not been relinquished under Treasury Regulation 25.2511-2", "The transfer is a completed gift of $1,500,000 because legal title passed to the trust", "The transfer is a completed gift but qualifies for the annual exclusion", "The transfer is partially complete for the income interest but incomplete for the remainder"]'::jsonb, 0, 'Under IRC Section 2511 and Treasury Regulation 25.2511-2(c), a gift is not complete if the donor retains the power to revest beneficial title in himself. Donovan''s revocation power means the transfer is incomplete, no taxable gift has occurred, and no Form 709 filing is required for this transfer. Choice B is incorrect because the transfer of legal title alone does not create a completed gift when the donor retains the power to reclaim the property.', 'medium', 3)
;

COMMIT;
